  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <section class="support-card" aria-labelledby="support-title">
      <h1 id="support-title">Contact support</h1>
      <p class="intro">Tell us how to reach you and our support team will follow up as soon as possible.</p>

      <form id="support-form" novalidate>
        <p class="required-note">Fields marked with <span aria-hidden="true">*</span> are required.</p>

        <div class="form-field">
          <label for="full-name">Full name <span aria-hidden="true">*</span></label>
          <input
            type="text"
            id="full-name"
            name="fullName"
            autocomplete="name"
            required
            aria-describedby="full-name-error"
          >
          <div class="error-message" id="full-name-error" aria-live="polite"></div>
        </div>

        <div class="form-field">
          <label for="email">Email address <span aria-hidden="true">*</span></label>
          <input
            type="email"
            id="email"
            name="email"
            autocomplete="email"
            required
            aria-describedby="email-error"
          >
          <div class="error-message" id="email-error" aria-live="polite"></div>
        </div>

        <div class="form-field">
          <label for="phone">Phone number <span class="helper-text">(optional)</span></label>
          <input
            type="tel"
            id="phone"
            name="phone"
            autocomplete="tel"
            inputmode="tel"
            pattern="^[+]?[(]?[0-9]{1,4}[)]?[-\s./0-9]*$"
            aria-describedby="phone-helper phone-error"
          >
          <p class="helper-text" id="phone-helper">Use digits, spaces, dashes, parentheses, or a leading plus sign, such as +1 555-123-4567.</p>
          <div class="error-message" id="phone-error" aria-live="polite"></div>
        </div>

        <button type="submit">Submit request</button>
        <p class="form-status" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#support-form");
    const statusMessage = document.querySelector("#form-status");

    const fields = {
      fullName: {
        input: document.querySelector("#full-name"),
        error: document.querySelector("#full-name-error"),
        messages: {
          valueMissing: "Enter your full name."
        }
      },
      email: {
        input: document.querySelector("#email"),
        error: document.querySelector("#email-error"),
        messages: {
          valueMissing: "Enter your email address.",
          typeMismatch: "Enter a valid email address, such as name@example.com."
        }
      },
      phone: {
        input: document.querySelector("#phone"),
        error: document.querySelector("#phone-error"),
        messages: {
          patternMismatch: "Enter a phone number using digits, spaces, dashes, parentheses, or a leading plus sign."
        }
      }
    };

    function getValidationMessage(field) {
      const { validity } = field.input;

      if (validity.valueMissing) {
        return field.messages.valueMissing;
      }

      if (validity.typeMismatch) {
        return field.messages.typeMismatch;
      }

      if (validity.patternMismatch) {
        return field.messages.patternMismatch;
      }

      return "";
